def test_list_datasets_pager(transport_name: str = "grpc"):
    client = ObservabilityClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_datasets), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            observability.ListDatasetsResponse(
                datasets=[
                    observability.Dataset(),
                    observability.Dataset(),
                    observability.Dataset(),
                ],
                next_page_token="abc",
            ),
            observability.ListDatasetsResponse(
                datasets=[],
                next_page_token="def",
            ),
            observability.ListDatasetsResponse(
                datasets=[
                    observability.Dataset(),
                ],
                next_page_token="ghi",
            ),
            observability.ListDatasetsResponse(
                datasets=[
                    observability.Dataset(),
                    observability.Dataset(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_datasets(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, observability.Dataset) for i in results)


