@pytest.mark.parametrize(
    "transport_name",
    [
        "rest",
    ],
)
def test_observability_client_transport_session_collision(transport_name):
    creds1 = ga_credentials.AnonymousCredentials()
    creds2 = ga_credentials.AnonymousCredentials()
    client1 = ObservabilityClient(
        credentials=creds1,
        transport=transport_name,
    )
    client2 = ObservabilityClient(
        credentials=creds2,
        transport=transport_name,
    )
    session1 = client1.transport.get_scope._session
    session2 = client2.transport.get_scope._session
    assert session1 != session2
    session1 = client1.transport.update_scope._session
    session2 = client2.transport.update_scope._session
    assert session1 != session2
    session1 = client1.transport.get_bucket._session
    session2 = client2.transport.get_bucket._session
    assert session1 != session2
    session1 = client1.transport.list_buckets._session
    session2 = client2.transport.list_buckets._session
    assert session1 != session2
    session1 = client1.transport.create_bucket._session
    session2 = client2.transport.create_bucket._session
    assert session1 != session2
    session1 = client1.transport.update_bucket._session
    session2 = client2.transport.update_bucket._session
    assert session1 != session2
    session1 = client1.transport.get_dataset._session
    session2 = client2.transport.get_dataset._session
    assert session1 != session2
    session1 = client1.transport.list_datasets._session
    session2 = client2.transport.list_datasets._session
    assert session1 != session2
    session1 = client1.transport.get_view._session
    session2 = client2.transport.get_view._session
    assert session1 != session2
    session1 = client1.transport.list_views._session
    session2 = client2.transport.list_views._session
    assert session1 != session2
    session1 = client1.transport.get_link._session
    session2 = client2.transport.get_link._session
    assert session1 != session2
    session1 = client1.transport.list_links._session
    session2 = client2.transport.list_links._session
    assert session1 != session2
    session1 = client1.transport.create_link._session
    session2 = client2.transport.create_link._session
    assert session1 != session2
    session1 = client1.transport.update_link._session
    session2 = client2.transport.update_link._session
    assert session1 != session2
    session1 = client1.transport.delete_link._session
    session2 = client2.transport.delete_link._session
    assert session1 != session2
    session1 = client1.transport.get_trace_scope._session
    session2 = client2.transport.get_trace_scope._session
    assert session1 != session2
    session1 = client1.transport.list_trace_scopes._session
    session2 = client2.transport.list_trace_scopes._session
    assert session1 != session2
    session1 = client1.transport.create_trace_scope._session
    session2 = client2.transport.create_trace_scope._session
    assert session1 != session2
    session1 = client1.transport.update_trace_scope._session
    session2 = client2.transport.update_trace_scope._session
    assert session1 != session2
    session1 = client1.transport.delete_trace_scope._session
    session2 = client2.transport.delete_trace_scope._session
    assert session1 != session2
    session1 = client1.transport.get_settings._session
    session2 = client2.transport.get_settings._session
    assert session1 != session2
    session1 = client1.transport.update_settings._session
    session2 = client2.transport.update_settings._session
    assert session1 != session2


def test_observability_grpc_transport_channel():
    channel = grpc.secure_channel("http://localhost/", grpc.local_channel_credentials())

    # Check that channel is used if provided.
    transport = transports.ObservabilityGrpcTransport(
        host="squid.clam.whelk",
        channel=channel,
    )
    assert transport.grpc_channel == channel
    assert transport._host == "squid.clam.whelk:443"
    assert transport._ssl_channel_credentials == None


